const body = $input.first().json.body || {};
const incoming = body.trip;
if (!incoming || typeof incoming !== 'object' || Array.isArray(incoming)) throw Error('Trip payload missing.');
function text(value, max) { return String(value ?? '').trim().slice(0, max); }
const t = {
  country:text(incoming.country,120), city:text(incoming.city,120),
  origin:text(incoming.origin,120), startDate:text(incoming.startDate,10),
  endDate:text(incoming.endDate,10), travelers:Number(incoming.travelers),
  budget:Number(incoming.budget), style: incoming.style==='slow'?'slow':'balanced',
  originAirport:text(incoming.originAirport,3).toUpperCase(),
  destinationAirport:text(incoming.destinationAirport,3).toUpperCase(),
  flightBudget:incoming.flightBudget===''||incoming.flightBudget==null ? 0 : Number(incoming.flightBudget)
};
if (![t.country,t.city,t.origin].every(s => s.length>0) ||
    !Number.isInteger(t.travelers) || t.travelers<1 || t.travelers>20 ||
    !Number.isFinite(t.budget) || t.budget<1 || t.budget>1000000 ||
    !Number.isFinite(t.flightBudget) || t.flightBudget<0 || t.flightBudget>1000000 ||
    (t.originAirport && !/^[A-Z]{3}$/.test(t.originAirport)) ||
    (t.destinationAirport && !/^[A-Z]{3}$/.test(t.destinationAirport))) throw Error('Invalid trip input.');
const parseDate = v => /^\d{4}-\d{2}-\d{2}$/.test(v) && !Number.isNaN(Date.parse(v+'T00:00:00Z')) ? Date.parse(v+'T00:00:00Z') : NaN;
const start = parseDate(t.startDate), end = parseDate(t.endDate);
if (!Number.isFinite(start)||!Number.isFinite(end)||end<start||(end-start)/86400000>=30) throw Error('Trip dates must span 1–30 days.');
return [{json:{trip:t,sourceQuery:encodeURIComponent(t.city.replace(/\s+/g,'_'))}}];

function extract(name) {
  const data = $(name).first().json;
  const value = data?.choices?.[0]?.message?.content;
  if (typeof value !== 'string' || !value.trim()) {
    const reason = String(data?.choices?.[0]?.finish_reason || 'unknown');
    const used = Number(data?.usage?.completion_tokens);
    throw Error('Missing final Groq text from '+name+' (finish_reason='+reason+', output_tokens='+(Number.isFinite(used)?used:'unknown')+'). Check the Groq node output and increase max_completion_tokens if needed.');
  }
  const cleaned = value.replace(/[<>]/g,'').trim();
  if (cleaned.length > 6500) throw Error('Groq agent report too long: '+name+'; ask the agent to shorten it before returning.');
  return cleaned;
}
const wiki = $('Destination Source').first().json;
let sourceUrl = null;
const candidate = wiki?.content_urls?.desktop?.page;
if (typeof candidate === 'string') {
  try {
    const u = new URL(candidate);
    if (u.protocol==='https:' && (u.hostname==='wikipedia.org' || u.hostname.endsWith('.wikipedia.org'))) sourceUrl=u.href;
  } catch {}
}
return [{json:{ok:true,sourceUrl,agents:[
  {name:'Destination researcher',findings:extract('Destination Agent')},
  {name:'Flight & hotel researcher',findings:extract('Flight & Stay Agent')},
  {name:'Journey composer',findings:extract('Journey Composer Agent')}
]}}];
